-- Floor 2 Rafters players (run after schema.sql). Rosters checked Oct 9, 2026 for 2026-27. Stats are 2025-26 regular season: G, PTS, REB, AST, STL, BLK.
-- goat = in the All-Time top 10 game; career = career numbers + titles/MVPs through the 2025-26 season (NBA only, from Basketball-Reference).
-- Never renumber ids: fans' lists point to them. Retired legends and players who left the NBA have active=false.
on conflict (id) do update set name=excluded.name,pos=excluded.pos,team=excluded.team,games=excluded.games,pts=excluded.pts,reb=excluded.reb,ast=excluded.ast,stl=excluded.stl,blk=excluded.blk,note=excluded.note,active=excluded.active,goat=excluded.goat,career=excluded.career;
